function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // Sensorimotor stage (0-2 years)
  ctx.lineWidth = 3;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/5, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/5, H/2 + 25);
  ctx.lineTo(W/5, H/2 + 50);
  ctx.stroke();
  ctx.font = '20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('Sensorimotor', W/5, H/2 + 60);

  // Preoperational stage (2-7 years)
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 25);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.fillText('Preoperational', W/2, H/2 + 60);
  ctx.beginPath();
  ctx.arc(W/2, H/2, 10 + 10*Math.sin(t), 0, 2*Math.PI);
  ctx.stroke();

  // Concrete operational stage (7-11 years)
  ctx.beginPath();
  ctx.arc(4*W/5, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(4*W/5, H/2 + 25);
  ctx.lineTo(4*W/5, H/2 + 50);
  ctx.stroke();
  ctx.fillText('Concrete Operational', 4*W/5, H/2 + 60);
  ctx.beginPath();
  ctx.moveTo(4*W/5, H/2);
  ctx.lineTo(4*W/5 + 20*Math.cos(t), H/2 + 20*Math.sin(t));
  ctx.stroke();

  // Formal operational stage (11-15 years and up)
  ctx.beginPath();
  ctx.arc(W/5, H/2 + 100, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/5, H/2 + 125);
  ctx.lineTo(W/5, H/2 + 150);
  ctx.stroke();
  ctx.fillText('Formal Operational', W/5, H/2 + 160);
  ctx.beginPath();
  ctx.arc(W/5, H/2 + 100, 10 + 10*Math.sin(t), 0, 2*Math.PI);
  ctx.stroke();

  ctx.beginPath();
  ctx.moveTo(W/5, H/2 + 100);
  ctx.lineTo(W/2, H/2 + 100);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 100);
  ctx.lineTo(4*W/5, H/2 + 100);
  ctx.stroke();
  ctx.restore();
}
